{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-4wADwA/src/parseGraph.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build-graph text format described by the CLI's specification.
 *
 * Returns `{ tasks, deps }` where `tasks` maps a task name to its cost and
 * `deps` maps a task name to the `Set` of names it depends on (only present
 * for names that appear as the target of a `dep` line). Every syntax or
 * reference failure throws a `CliError` with exit code 2.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const tasks = new Map()
  const deps = new Map()
  const usedNames = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, Number.parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const name = words[1]
      const depNames = words.slice(2)
      for (const candidate of [name, ...depNames]) {
        if (!NAME_RE.test(candidate)) {
          throw new CliError(`error: line ${lineNumber}: invalid task name ${candidate}`, 2)
        }
      }
      usedNames.push(name, ...depNames)
      let set = deps.get(name)
      if (!set) {
        set = new Set()
        deps.set(name, set)
      }
      for (const depName of depNames) set.add(depName)
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(`error: unknown task ${name}`, 2)
    }
  }

  return { tasks, deps }
}
"}

