{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-4wADwA/src/pack.js","content":"/**
 * Priority is the cost of the longest chain that begins at a task, counting
 * its own cost and then the costs of the tasks that (transitively) depend on
 * it, down to any task that nothing depends on.
 */
function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const depName of depSet) {
      dependents.get(depName).push(name)
    }
  }

  const priorities = new Map()
  function resolve(name) {
    const cached = priorities.get(name)
    if (cached !== undefined) return cached
    let best = 0
    for (const dependent of dependents.get(name)) {
      const value = resolve(dependent)
      if (value > best) best = value
    }
    const priority = tasks.get(name) + best
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) resolve(name)
  return priorities
}

/**
 * Simulates the build graph on `workerCount` workers using greedy list
 * scheduling: at every instant, each free worker (smallest index first)
 * takes the highest-priority ready task (ties broken by ascending name).
 */
export function packSchedule(tasks, deps, workerCount) {
  const priorities = computePriorities(tasks, deps)

  function sortedDeps(name) {
    const set = deps.get(name)
    return set ? [...set] : []
  }

  const workerFreeAt = new Array(workerCount).fill(0)
  const workerRuns = Array.from({ length: workerCount }, () => [])
  const scheduled = new Map()
  const remaining = new Set(tasks.keys())

  let time = 0
  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeWorker = -1
      for (let i = 0; i < workerFreeAt.length; i++) {
        if (workerFreeAt[i] <= time) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of remaining) {
        const ready = sortedDeps(name).every((depName) => {
          const depTiming = scheduled.get(depName)
          return depTiming && depTiming.finish <= time
        })
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best)
      const start = time
      const finish = start + cost
      scheduled.set(best, { start, finish })
      workerRuns[freeWorker].push({ name: best, start, finish })
      workerFreeAt[freeWorker] = finish
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    const future = workerFreeAt.filter((t) => t > time)
    if (future.length === 0) break
    time = Math.min(...future)
  }

  let makespan = 0
  for (const timing of scheduled.values()) {
    if (timing.finish > makespan) makespan = timing.finish
  }

  return { workerRuns, makespan }
}
"}

