{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-5gG0pI/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { LineError } from './errors.js'
import { simulate } from './engine.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(results) {
  return results
    .map((result) => (result.allow ? `${result.tick} ${result.key} allow` : `${result.tick} ${result.key} deny ${result.deniedBy}`))
    .join('')
}

function formatSummary(results) {
  const totals = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const result of results) {
    let entry = totals.get(result.key)
    if (!entry) {
      entry = { allowed: 0, denied: 0 }
      totals.set(result.key, entry)
    }
    if (result.allow) {
      entry.allowed++
      totalAllowed++
    } else {
      entry.denied++
      totalDenied++
    }
  }
  const keys = [...totals.keys()].sort()
  let out = ''
  for (const key of keys) {
    const entry = totals.get(key)
    out += `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const text = readStdin()

  let results
  try {
    results = simulate(text)
  } catch (error) {
    if (error instanceof LineError) {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(2)
    }
    throw error
  }

  const output = mode === 'replay' ? replayLines(results) : formatSummary(results)
  process.stdout.write(output)
}

function replayLines(results) {
  return results
    .map((result) => (result.allow ? `${result.tick} ${result.key} allow\n` : `${result.tick} ${result.key} deny ${result.deniedBy}\n`))
    .join('')
}

main()
"}

