{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-B8Rann/src/evaluator.js","content":"/**
 * Evaluates a parsed sheet's cells. Each cell is evaluated at most once
 * (memoized); a cell whose evaluation reaches itself, directly or through
 * other cells, comes back `#CYCLE!` because a re-entrant request for a cell
 * still being computed yields that error, which then propagates like any
 * other error through the normal operator/function rules.
 */

import { numV, boolV, errV, asNumber, compareValues } from './values.js'
import { resolveAddress } from './address.js'
import { expandRange } from './range.js'

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const VARIADIC_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

export class Evaluator {
  constructor(sheet) {
    this.sheet = sheet // Map<key, { parsed, ... }>
    this.cache = new Map()
    this.visiting = new Set()
  }

  evaluate(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    const decl = this.sheet.get(key)
    if (!decl) return numV(0)
    if (this.visiting.has(key)) return errV('#CYCLE!')

    this.visiting.add(key)
    let result
    if (decl.parsed.kind === 'literal') {
      result = decl.parsed.value
    } else if (decl.parsed.ast === null) {
      result = errV('#ERR!')
    } else {
      result = evalExpr(decl.parsed.ast, this)
    }
    this.visiting.delete(key)
    this.cache.set(key, result)
    return result
  }
}

/** Evaluates an argument node, expanding a range into every cell it covers. */
function flattenArg(node, ctx) {
  if (node.type === 'Range') {
    const cells = expandRange(node.from, node.to)
    if (!cells) return [errV('#REF!')]
    return cells.map((c) => ctx.evaluate(c.key))
  }
  return [evalExpr(node, ctx)]
}

function firstError(values) {
  return values.find((v) => v.t === 'err')
}

function arith(op, a, b) {
  let value
  switch (op) {
    case '+': value = a + b; break
    case '-': value = a - b; break
    case '*': value = a * b; break
    case '/': value = a / b; break
    case '^': value = Math.pow(a, b); break
    default: throw new Error(`unreachable operator: ${op}`)
  }
  return Number.isFinite(value) ? numV(value) : errV('#DIV/0!')
}

function evalExpr(node, ctx) {
  switch (node.type) {
    case 'Num':
      return numV(node.value)
    case 'Bool':
      return boolV(node.value)
    case 'Address': {
      const addr = resolveAddress(node.letters, node.digits)
      if (!addr) return errV('#REF!')
      return ctx.evaluate(addr.key)
    }
    case 'Unary': {
      const operand = evalExpr(node.operand, ctx)
      if (operand.t === 'err') return operand
      const num = asNumber(operand)
      if (num.t === 'err') return num
      return numV(node.op === '-' ? -num.v : num.v)
    }
    case 'Bin':
      return evalBin(node, ctx)
    case 'Call':
      return evalCall(node, ctx)
    default:
      throw new Error(`unreachable node type: ${node.type}`)
  }
}

function evalBin(node, ctx) {
  const left = evalExpr(node.left, ctx)
  if (COMPARE_OPS.has(node.op)) {
    if (left.t === 'err') return left
    const right = evalExpr(node.right, ctx)
    if (right.t === 'err') return right
    const cmp = compareValues(left, right)
    switch (node.op) {
      case '=': return boolV(cmp === 0)
      case '<>': return boolV(cmp !== 0)
      case '<': return boolV(cmp < 0)
      case '<=': return boolV(cmp <= 0)
      case '>': return boolV(cmp > 0)
      case '>=': return boolV(cmp >= 0)
      default: throw new Error(`unreachable comparison: ${node.op}`)
    }
  }
  const leftNum = asNumber(left)
  if (leftNum.t === 'err') return leftNum
  const right = evalExpr(node.right, ctx)
  const rightNum = asNumber(right)
  if (rightNum.t === 'err') return rightNum
  if (node.op === '/' && rightNum.v === 0) return errV('#DIV/0!')
  return arith(node.op, leftNum.v, rightNum.v)
}

function evalCall(node, ctx) {
  const name = node.name
  if (VARIADIC_FUNCS.has(name)) {
    if (node.args.length < 1) return errV('#ERR!')
    const flat = node.args.flatMap((a) => flattenArg(a, ctx))
    const err = firstError(flat)
    if (err) return err
    return aggregate(name, flat)
  }
  if (name === 'ABS') {
    if (node.args.length !== 1) return errV('#ERR!')
    const flat = flattenArg(node.args[0], ctx)
    const err = firstError(flat)
    if (err) return err
    const num = asNumber(flat[0])
    if (num.t === 'err') return num
    return numV(Math.abs(num.v))
  }
  if (name === 'IF') {
    if (node.args.length !== 3) return errV('#ERR!')
    const condFlat = flattenArg(node.args[0], ctx)
    const condErr = firstError(condFlat)
    if (condErr) return condErr
    const condNum = asNumber(condFlat[0])
    if (condNum.t === 'err') return condNum
    const branch = condNum.v !== 0 ? node.args[1] : node.args[2]
    const branchFlat = flattenArg(branch, ctx)
    const branchErr = firstError(branchFlat)
    if (branchErr) return branchErr
    return branchFlat[0]
  }
  return errV('#NAME?')
}

function aggregate(name, flat) {
  if (name === 'COUNT') {
    return numV(flat.filter((v) => v.t === 'num').length)
  }
  const nums = []
  for (const v of flat) {
    const num = asNumber(v)
    if (num.t === 'err') return num
    nums.push(num.v)
  }
  switch (name) {
    case 'SUM':
      return numV(nums.reduce((a, b) => a + b, 0))
    case 'MIN':
      return numV(Math.min(...nums))
    case 'MAX':
      return numV(Math.max(...nums))
    case 'AVG':
      return numV(nums.reduce((a, b) => a + b, 0) / nums.length)
    default:
      throw new Error(`unreachable function: ${name}`)
  }
}
"}

