      return numV(node.op === '-' ? -num.v : num.v)
    }
    case 'Bin':
      return evalBin(node, ctx)
    case 'Call':
      return evalCall(node, ctx)
    default:
      throw new Error(`unreachable node type: ${node.type}`)
  }
}

function evalBin(node, ctx) {
  const left = evalExpr(node.left, ctx)
  if (COMPARE_OPS.has(node.op)) {
    if (left.t === 'err') return left
    const right = evalExpr(node.right, ctx)
    if (right.t === 'err') return right
    const cmp = compareValues(left, right)
    switch (node.op) {
      case '=': return boolV(cmp === 0)
      case '<>': return boolV(cmp !== 0)
      case '<': return boolV(cmp < 0)
      case '<=': return boolV(cmp <= 0)
      case '>': return boolV(cmp > 0)
      case '>=': return boolV(cmp >= 0)
      default: throw new Error(`unreachable comparison: ${node.op}`)
    }
  }
  const leftNum = asNumber(left)
  if (leftNum.t === 'err') return leftNum
  const right = evalExpr(node.right, ctx)
  const rightNum = asNumber(right)
  if (rightNum.t === 'err') return rightNum
  if (node.op === '/' && rightNum.v === 0) return errV('#DIV/0!')
  return arith(node.op, leftNum.v, rightNum.v)
}

function evalCall(node, ctx) {
  const name = node.name
  if (VARIADIC_FUNCS.has(name)) {
    if (node.args.length < 1) return errV('#ERR!')
    const flat = node.args.flatMap((a) => flattenArg(a, ctx))
    const err = firstError(flat)
    if (err) return err
    return aggregate(name, flat)
  }
  if (name === 'ABS') {
    if (node.args.length !== 1) return errV('#ERR!')
    const flat = flattenArg(node.args[0], ctx)
    const err = firstError(flat)
    if (err) return err
    const num = asNumber(flat[0])
    if (num.t === 'err') return num
    return numV(Math.abs(num.v))
  }
  if (name === 'IF') {
    if (node.args.length !== 3) return errV('#ERR!')
    const condFlat = flattenArg(node.args[0], ctx)
    const condErr = firstError(condFlat)
    if (condErr) return condErr
    const condNum = asNumber(condFlat[0])
    if (condNum.t === 'err') return condNum
    const branch = condNum.v !== 0 ? node.args[1] : node.args[2]
    const branchFlat = flattenArg(branch, ctx)
    const branchErr = firstError(branchFlat)
    if (branchErr) return branchErr
    return branchFlat[0]
  }
  return errV('#NAME?')
}

function aggregate(name, flat) {
  if (name === 'COUNT') {
    return numV(flat.filter((v) => v.t === 'num').length)
  }
  const nums = []
  for (const v of flat) {
    const num = asNumber(v)
    if (num.t === 'err') return num
    nums.push(num.v)
  }
  switch (name) {
    case 'SUM':
      return numV(nums.reduce((a, b) => a + b, 0))
    case 'MIN':
      return numV(Math.min(...nums))
    case 'MAX':
      return numV(Math.max(...nums))
    case 'AVG':
      return numV(nums.reduce((a, b) => a + b, 0) / nums.length)
    default:
      throw new Error(`unreachable function: ${name}`)
  }
}
"}

