 * Collects the cells a formula names directly, independent of how (or
 * whether) it evaluates: every address and every range's expanded cells,
 * regardless of which branch of an `IF` would actually be taken.
 */

import { resolveAddress } from './address.js'
import { expandRange } from './range.js'

/** Returns the distinct in-range addresses `ast` names, ordered by column then row. */
export function collectDeps(ast) {
  const seen = new Map() // key -> { col, row }
  walk(ast, seen)
  return [...seen.values()].sort((a, b) => (a.col - b.col) || (a.row - b.row)).map((a) => a.key ?? `${a.letters}${a.row}`)
}

function add(seen, addr) {
  if (!seen.has(addr.key)) seen.set(addr.key, addr)
}

function walk(node, seen) {
  switch (node.type) {
    case 'Num':
    case 'Bool':
      return
    case 'Address': {
      const addr = resolveAddress(node.letters, node.digits)
      if (addr) add(seen, addr)
      return
    }
    case 'Range': {
      const cells = expandRange(node.from, node.to)
      if (cells) for (const c of cells) add(seen, c)
      return
    }
    case 'Unary':
      walk(node.operand, seen)
      return
    case 'Bin':
      walk(node.left, seen)
      walk(node.right, seen)
      return
    case 'Call':
      for (const arg of node.args) walk(arg, seen)
      return
    default:
      throw new Error(`unreachable node type: ${node.type}`)
  }
}
"}

