{"file_path":"src/errors.js","content":"/**
 * Error types the CLI distinguishes when deciding what to print and which
 * exit code to use.
 */

/** A validation failure that exits with a given status and prints one line. */
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

/** A dependency cycle found while scheduling; carries the reported path. */
export class CycleError extends Error {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.names = names
  }
}
"}

{"file_path":"src/parse.js","content":"/**
 * Parses the build-graph text format into a graph of tasks and their
 * dependencies, per the rules in the task description.
 */
import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

/**
 * @param {string} input the raw standard input
 * @returns {{ tasks: Map<string, { name: string, cost: number }>, deps: Map<string, string[]> }}
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depReferences = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { name, cost: Number(costStr) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      const subject = words[1]
      const dependencies = words.slice(2)
      depReferences.push(subject, ...dependencies)
      const list = deps.get(subject) ?? []
      for (const d of dependencies) {
        if (!list.includes(d)) list.push(d)
      }
      deps.set(subject, list)
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of depReferences) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`, 2)
    }
  }

  return { tasks, deps }
}
"}

{"file_path":"src/graph.js","content":"/**
 * Graph algorithms shared by the `waves`, `explain` and `pack` commands:
 * cycle detection, the unlimited-worker schedule, chain priorities, and the
 * limited-worker pack simulation.
 */
import { CycleError } from './errors.js'

/**
 * Depth-first cycle check. Visits tasks and, within each task, its
 * dependencies, both in ascending name order, and reports the first cycle
 * found as a {@link CycleError}.
 */
export function detectCycle(tasks, deps) {
  const state = new Map()
  for (const name of tasks.keys()) state.set(name, 0)
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    const depList = [...(deps.get(node) ?? [])].sort()
    for (const dep of depList) {
      const depState = state.get(dep)
      if (depState === 1) {
        const idx = stack.indexOf(dep)
        throw new CycleError([...stack.slice(idx), dep])
      }
      if (depState === 0) visit(dep)
    }
    state.set(node, 2)
    stack.pop()
  }

  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === 0) visit(name)
  }
}

/**
 * The unlimited-worker schedule: each task's wave depth, start and finish.
 */
export function computeSchedule(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function getDepth(name) {
    if (depth.has(name)) return depth.get(name)
    const depList = deps.get(name) ?? []
    const value = depList.length === 0 ? 0 : 1 + Math.max(...depList.map(getDepth))
    depth.set(name, value)
    return value
  }

  function getFinish(name) {
    if (finish.has(name)) return finish.get(name)
    const depList = deps.get(name) ?? []
    const s = depList.length === 0 ? 0 : Math.max(...depList.map(getFinish))
    start.set(name, s)
    const f = s + tasks.get(name).cost
    finish.set(name, f)
    return f
  }

  for (const name of tasks.keys()) {
    getDepth(name)
    getFinish(name)
  }

  return { depth, start, finish }
}

/**
 * Each task's priority for `pack`: the cost of the longest chain of costs
 * from the task down through its dependents to one nothing depends on.
 */
export function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depList] of deps) {
    for (const dep of depList) {
      if (dependents.has(dep)) dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  function get(name) {
    if (priority.has(name)) return priority.get(name)
    const dts = dependents.get(name) ?? []
    const value = tasks.get(name).cost + (dts.length === 0 ? 0 : Math.max(...dts.map(get)))
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) get(name)
  return priority
