function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Groups the changes from both sides into regions: a run of consecutive
 * base lines covered by one or more changes, absorbing any further change
 * that starts at or before the region's current end.
 */
function buildRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    const region = { baseStart: changes[i].baseStart, baseEnd: changes[i].baseEnd, changes: [changes[i]] }
    i++
    while (i < changes.length && changes[i].baseStart <= region.baseEnd) {
      region.baseEnd = Math.max(region.baseEnd, changes[i].baseEnd)
      region.changes.push(changes[i])
      i++
    }
    regions.push(region)
  }
  return regions
}

/**
 * Resolves a side's replacement lines for a region from that side's own
 * changes within it: from the earliest change's start, moved back to the
 * region's start, to the latest change's end, moved forward to the
 * region's end.
 */
function sideLines(sideDoc, sideChanges, region, baseDoc) {
  if (sideChanges.length === 0) return baseDoc.slice(region.baseStart, region.baseEnd)
  const first = sideChanges[0]
  const last = sideChanges[sideChanges.length - 1]
  const start = first.sideStart - (first.baseStart - region.baseStart)
  const end = last.sideEnd + (region.baseEnd - last.baseEnd)
  return sideDoc.slice(start, end)
}

/**
 * Computes the ordered list of stable segments, resolved regions and
 * conflicts that make up the three-way merge of `mine` and `theirs` against
 * `base`.
 *
 * Each item is one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function computeMerge(mine, base, theirs) {
  const mineChanges = diffChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = diffChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))

  const combined = [...mineChanges, ...theirsChanges].sort((a, b) => a.baseStart - b.baseStart)
  const regions = buildRegions(combined)

  const items = []
  let pos = 0

  for (const region of regions) {
    if (region.baseStart > pos) items.push({ kind: 'stable', lines: base.slice(pos, region.baseStart) })

    if (region.changes.length === 1) {
      const change = region.changes[0]
      const doc = change.side === 'mine' ? mine : theirs
      items.push({ kind: change.side, lines: doc.slice(change.sideStart, change.sideEnd) })
    } else {
      const mineSide = region.changes.filter(c => c.side === 'mine')
      const theirsSide = region.changes.filter(c => c.side === 'theirs')
      const mineResolved = sideLines(mine, mineSide, region, base)
      const theirsResolved = sideLines(theirs, theirsSide, region, base)
      const baseResolved = base.slice(region.baseStart, region.baseEnd)

      if (arraysEqual(mineResolved, theirsResolved)) {
        items.push({ kind: 'both', lines: mineResolved })
      } else if (arraysEqual(mineResolved, baseResolved)) {
        items.push({ kind: 'theirs', lines: theirsResolved })
      } else if (arraysEqual(theirsResolved, baseResolved)) {
        items.push({ kind: 'mine', lines: mineResolved })
      } else {
        items.push({ kind: 'conflict', mine: mineResolved, base: baseResolved, theirs: theirsResolved })
      }
    }

    pos = region.baseEnd
  }

  if (pos < base.length) items.push({ kind: 'stable', lines: base.slice(pos, base.length) })

  return items
}
