{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-TiyKK5/src/render.js","content":"/**
 * Renders merge items (see computeMerge) to the lines of a `merge` or
 * `merge2` document. Returns the lines and whether any conflict was
 * written.
 */
export function renderMerge(items, { includeBase }) {
  const lines = []
  let conflict = false

  for (const item of items) {
    if (item.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine', ...item.mine)
      if (includeBase) lines.push('||||||| base', ...item.base)
      lines.push('=======', ...item.theirs, '>>>>>>> theirs')
    } else {
      lines.push(...item.lines)
    }
  }

  return { lines, conflict }
}

/**
 * Renders merge items to the lines of the `regions` report. Returns the
 * lines and whether any conflict was written.
 */
export function renderRegions(items) {
  const lines = []
  let conflict = false

  for (const item of items) {
    if (item.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${item.mine.length} base=${item.base.length} theirs=${item.theirs.length}`)
    } else {
      lines.push(`${item.kind} ${item.lines.length}`)
    }
  }

  return { lines, conflict }
}
"}

