/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { parseInput, ParseError } from './parse.js'
import { computeMerge } from './merge.js'
import { renderMerge, renderRegions } from './render.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  let parts
  try {
    parts = parseInput(readStdin())
  } catch (err) {
    if (err instanceof ParseError) fail(err.message)
    throw err
  }
  const [mine, base, theirs] = parts

  const items = computeMerge(mine, base, theirs)
  const rendered =
    mode === 'regions' ? renderRegions(items) : renderMerge(items, { includeBase: mode === 'merge' })

  const out = rendered.lines.length > 0 ? `${rendered.lines.join('\n')}\n` : ''
  process.stdout.write(out)
  process.exit(rendered.conflict ? 1 : 0)
}

main()
"}

