{"file_path":"src/assign.js","content":"import { SpecError } from './errors.js'
import { formatPath, makeTable } from './nodes.js'

/**
 * Walks `parts` (dotted-name segments, none of them the final leaf)
 * starting from `node`, creating tables along the way as needed. Walking
 * through an array of tables uses its last element, recorded in the
 * returned path as an index segment. Returns the table reached and the
 * path to it, counted from the root.
 */
export function walkIntermediate(node, parts, basePath) {
  let path = basePath.slice()
  for (const name of parts) {
    path = path.concat([name])
    let next = node.entries.get(name)
    if (next === undefined) {
      next = makeTable()
      node.entries.set(name, next)
    } else if (next.kind === 'array-of-tables') {
      const index = next.items.length - 1
      next = next.items[index]
      path = path.concat([index])
    } else if (next.kind !== 'table') {
      throw new SpecError(`${formatPath(path)} is not a table`)
    }
    node = next
  }
  return { node, path }
}

/**
 * Assigns `value` at `parts` inside `table` (a real table or an inline
 * table under construction), creating intermediate tables as needed.
 * `basePath` is the path to `table` itself, used to report the full path
 * from the document root when something goes wrong.
 */
export function assignValue(table, basePath, parts, value) {
  const allButLast = parts.slice(0, -1)
  const last = parts[parts.length - 1]
  const { node: parent, path: parentPath } = walkIntermediate(table, allButLast, basePath)
  const fullPath = parentPath.concat([last])
  if (parent.entries.has(last)) {
    throw new SpecError(`key ${formatPath(fullPath)} is defined twice`)
  }
  parent.entries.set(last, value)
  return fullPath
}

/**
 * Applies a `[name]` or `[[name]]` header against the document root,
 * returning the table that becomes current and the path to it (which,
 * for an array of tables, ends with the index of the freshly appended
 * element).
 */
export function applyHeader(root, isArray, parts) {
  const allButLast = parts.slice(0, -1)
  const last = parts[parts.length - 1]
  const { node: parent, path: parentPath } = walkIntermediate(root, allButLast, [])
  const fullPath = parentPath.concat([last])
  const existing = parent.entries.get(last)

  if (!isArray) {
    if (existing === undefined) {
      const table = makeTable()
      table.headerOpened = true
      parent.entries.set(last, table)
      return { table, path: fullPath }
    }
    if (existing.kind !== 'table') {
      throw new SpecError(`${formatPath(fullPath)} is not a table`)
    }
    if (existing.headerOpened) {
      throw new SpecError(`table ${formatPath(fullPath)} is defined twice`)
    }
    existing.headerOpened = true
    return { table: existing, path: fullPath }
  }

  let arrayNode = existing
  if (arrayNode === undefined) {
    arrayNode = { kind: 'array-of-tables', items: [] }
    parent.entries.set(last, arrayNode)
  } else if (arrayNode.kind !== 'array-of-tables') {
    throw new SpecError(`${formatPath(fullPath)} is not an array of tables`)
  }
  const table = makeTable()
  arrayNode.items.push(table)
  return { table, path: fullPath.concat([arrayNode.items.length - 1]) }
}
"}

