{"file_path":"src/values.js","content":"import { SpecError } from './errors.js'
import { parseBasicString, parseLiteralString, parseDottedName } from './names.js'
import { makeTable } from './nodes.js'
import { assignValue } from './assign.js'

const INTEGER_RE = /^[+-]?\d(?:_?\d)*$/
const FLOAT_RE = /^[+-]?\d(?:_?\d)*(?:\.\d(?:_?\d)*(?:[eE][+-]?\d(?:_?\d)*)?|[eE][+-]?\d(?:_?\d)*)$/

function isTokenStop(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

/**
 * Parses one value at the scanner's current position. `path` is the path
 * (from the document root) at which this value will end up, used only to
 * report duplicate-key errors found while parsing a nested inline table.
 */
export function parseValue(scanner, path) {
  if (scanner.atEnd() || scanner.peek() === ',' || scanner.peek() === ']' || scanner.peek() === '}') {
    throw new SpecError('expected a value')
  }
  const c = scanner.peek()
  if (c === '"') return { kind: 'string', value: parseBasicString(scanner) }
  if (c === "'") return { kind: 'string', value: parseLiteralString(scanner) }
  if (c === '[') return parseArrayValue(scanner, path)
  if (c === '{') return parseInlineTable(scanner, path)

  const start = scanner.pos
  while (!scanner.atEnd() && !isTokenStop(scanner.peek())) scanner.pos++
  const token = scanner.s.slice(start, scanner.pos)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  if (INTEGER_RE.test(token)) return { kind: 'integer', value: Number(token.replace(/_/g, '')) }
  if (FLOAT_RE.test(token)) return { kind: 'float', value: Number(token.replace(/_/g, '')) }
  throw new SpecError(`invalid value ${token}`)
}

function parseArrayValue(scanner, path) {
  scanner.pos++ // '['
  const items = []
  scanner.skipWs()
  if (!scanner.atEnd() && scanner.peek() === ']') {
    scanner.pos++
    return { kind: 'array', items }
  }
  let index = 0
  for (;;) {
    scanner.skipWs()
    if (scanner.atEnd()) throw new SpecError('unterminated array')
    items.push(parseValue(scanner, path.concat([index])))
    index++
    scanner.skipWs()
    if (scanner.atEnd()) throw new SpecError('unterminated array')
    if (scanner.peek() === ',') {
      scanner.pos++
      scanner.skipWs()
      if (!scanner.atEnd() && scanner.peek() === ']') {
        scanner.pos++
        break
      }
      continue
    }
    if (scanner.peek() === ']') {
      scanner.pos++
      break
    }
    throw new SpecError('unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTable(scanner, path) {
  scanner.pos++ // '{'
  const table = makeTable()
  scanner.skipWs()
  if (!scanner.atEnd() && scanner.peek() === '}') {
    scanner.pos++
    return table
  }
  for (;;) {
    scanner.skipWs()
    if (scanner.atEnd()) throw new SpecError('unterminated inline table')
    const parts = parseDottedName(scanner)
    scanner.skipWs()
