{"file_path":"src/document.js","content":"import { SpecError, ParseError } from './errors.js'
import { Scanner, firstNonWs } from './scanner.js'
import { parseDottedName } from './names.js'
import { parseValue } from './values.js'
import { makeTable, formatPath } from './nodes.js'
import { walkIntermediate, applyHeader } from './assign.js'

function parseHeaderLine(scanner) {
  scanner.skipWs()
  scanner.pos++ // first '['
  let isArray = false
  if (!scanner.atEnd() && scanner.peek() === '[') {
    isArray = true
    scanner.pos++
  }
  const parts = parseDottedName(scanner)
  scanner.skipWs()
  if (scanner.atEnd() || scanner.peek() !== ']') throw new SpecError('unterminated table header')
  scanner.pos++
  if (isArray) {
    if (scanner.atEnd() || scanner.peek() !== ']') throw new SpecError('unterminated table header')
    scanner.pos++
  }
  scanner.skipWs()
  if (!scanner.atEnd()) throw new SpecError('trailing text after a table header')
  return { isArray, parts }
}

function processKeyValueLine(scanner, currentTable, currentPath) {
  const parts = parseDottedName(scanner)
  scanner.skipWs()
  if (scanner.atEnd() || scanner.peek() !== '=') throw new SpecError('expected key = value')
  scanner.pos++
  scanner.skipWs()

  const allButLast = parts.slice(0, -1)
  const last = parts[parts.length - 1]
  const { node: parent, path: parentPath } = walkIntermediate(currentTable, allButLast, currentPath)
  const fullPath = parentPath.concat([last])
  if (parent.entries.has(last)) {
    throw new SpecError(`key ${formatPath(fullPath)} is defined twice`)
  }
  const value = parseValue(scanner, fullPath)
  scanner.skipWs()
  if (!scanner.atEnd()) throw new SpecError('trailing text after a value')
  parent.entries.set(last, value)
}

/** Parses a whole configuration document into a table node, the root. */
export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const idx = firstNonWs(line)
    if (idx === line.length) continue
    const first = line[idx]
    if (first === '#' || first === ';') continue

    try {
      const scanner = new Scanner(line)
      if (first === '[') {
        const { isArray, parts } = parseHeaderLine(scanner)
        const { table, path } = applyHeader(root, isArray, parts)
        currentTable = table
        currentPath = path
      } else {
        processKeyValueLine(scanner, currentTable, currentPath)
      }
    } catch (e) {
      if (e instanceof SpecError) throw new ParseError(lineNo, e.reason)
      throw e
    }
  }

  return root
}
"}

