{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-YzwZVG/src/parser.js","content":"import { CliError } from './errors.js'

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

/**
 * Parses the election description in `input` into `{ candidates, ballots }`,
 * where `candidates` is the declared name array and each ballot is
 * `{ count, names }`. Throws `CliError` at the first line that violates the
 * grammar.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new CliError('expected candidates <name>...', lineNumber)
      }
      const declared = []
      for (const name of tokens.slice(1)) {
        if (!NAME.test(name)) {
          throw new CliError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new CliError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        declared.push(name)
      }
      candidates = declared
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new CliError('expected ballot <count> <candidate>...', lineNumber)
      }
      const count = tokens[1]
      if (!COUNT.test(count)) {
        throw new CliError('count must be a positive integer', lineNumber)
      }
      const names = []
      const seen = new Set()
      for (const name of tokens.slice(2)) {
        if (!candidateSet.has(name)) {
          throw new CliError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new CliError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count: Number(count), names })
    } else {
      throw new CliError(`unknown directive ${word}`, lineNumber)
    }
  }

  if (candidates === null) {
    throw new CliError('no candidates')
  }

  return { candidates, ballots }
}
"}

