function consumeDigitRun(sc, isDigitFn) {
  let count = 0
  let lastWasDigit = false
  while (!sc.eof()) {
    const c = sc.peek()
    if (isDigitFn(c)) {
      sc.advance()
      count++
      lastWasDigit = true
      continue
    }
    if (c === '_' && lastWasDigit && isDigitFn(sc.peek(1))) {
      sc.advance()
      lastWasDigit = false
      continue
    }
    break
  }
  return count
