{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-mq3yV7/src/policies.js","content":"/**
 * The two policy kinds a route can chain: token buckets and sliding
 * windows. Each keeps one independent state per key, created the first
 * time that key reaches it.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // Tokens are tracked scaled by `per` so that "refill tokens for every
    // per ticks" accumulates as an exact integer, never a rounded float.
    this.scaledCapacity = capacity * per
    this.states = new Map()
  }

  _state(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { scaledTokens: this.scaledCapacity, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this._state(key, tick)
    const delta = tick - state.lastTick
    if (delta > 0n) {
      state.scaledTokens += this.refill * delta
      if (state.scaledTokens > this.scaledCapacity) state.scaledTokens = this.scaledCapacity
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.scaledTokens >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.scaledTokens -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  _state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this._state(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.length && state[cut] <= threshold) cut++
    if (cut > 0) state.splice(0, cut)
  }

  allows(key) {
    const state = this.states.get(key) || []
    return BigInt(state.length) < this.limit
  }

  record(key, tick) {
    const state = this._state(key)
    state.push(tick)
  }
}
"}

