{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-mq3yV7/src/parser.js","content":"/**
 * Turns a limiter file's text into declared policies, routes and events,
 * or throws a `ParseError` naming the offending line.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(lineNo, reason) {
    super(reason)
    this.lineNo = lineNo
  }
}

function parseCount(token, field, min, lineNo) {
  if (!INT_RE.test(token)) {
    throw new ParseError(lineNo, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < min) {
    throw new ParseError(lineNo, `${field} must be an integer of at least ${min}`)
  }
  return value
}

export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capTok, refillTok, perTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = parseCount(capTok, 'capacity', 1n, lineNo)
      const refill = parseCount(refillTok, 'refill', 0n, lineNo)
      const per = parseCount(perTok, 'per', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitTok, spanTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = parseCount(limitTok, 'limit', 0n, lineNo)
      const span = parseCount(spanTok, 'span', 1n, lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routesByPrefix.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      const routePolicies = []
      for (const name of policyNames) {
        const policy = policies.get(name)
        if (!policy) throw new ParseError(lineNo, `unknown policy ${name}`)
        routePolicies.push(policy)
      }
      const route = { prefix, policies: routePolicies }
      routesByPrefix.set(prefix, route)
      routes.push(route)
    } else if (directive === 'event') {
      seenEvent = true
      if (tokens.length !== 3) {
        throw new ParseError(lineNo, 'expected event <tick> <key>')
      }
      const [, tickTok, key] = tokens
      const tick = parseCount(tickTok, 'tick', 0n, lineNo)
      if (!NAME_RE.test(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  return { routes, events }
}
"}

