 * Replays a parsed limiter file's events against its routes, producing a
 * verdict per event and running totals per key.
 */

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (!best || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

export function runSimulation({ routes, events }) {
  const results = []
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    let allow = true
    let denyName = null

    if (route) {
      for (const policy of route.policies) policy.advance(key, tick)
      for (const policy of route.policies) {
        if (!policy.allows(key)) {
          allow = false
          denyName = policy.name
          break
        }
      }
      if (allow) {
        for (const policy of route.policies) policy.record(key, tick)
      }
    }

    results.push({ tick, key, allow, denyName })

    let stat = perKey.get(key)
    if (!stat) {
      stat = { allowed: 0n, denied: 0n }
      perKey.set(key, stat)
    }
    if (allow) {
      stat.allowed++
      totalAllowed++
    } else {
      stat.denied++
      totalDenied++
    }
  }

  return { results, perKey, totalAllowed, totalDenied }
}
"}

