{"file_path":"src/uri.js","content":"/**
 * URI reference parsing, normalization and resolution per RFC 3986's
 * generic syntax (sections 3, 5.2.2, 5.2.4 and 5.3), restricted to the
 * literal rules the task spells out.
 */

/** Raised for any of the five spec-defined failure conditions. */
export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

const HEX = /^[0-9a-fA-F]$/
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/**
 * Splits a URI reference into scheme, authority, path, query and
 * fragment. Each of scheme, authority, query and fragment is `null`
 * when absent, and a string (possibly empty) when present; path is
 * always a string.
 */
export function parseReference(s) {
  let rest = s
  let scheme = null
  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1) {
    const prefix = rest.slice(0, colonIdx)
    if (!/[/?#]/.test(prefix)) {
      scheme = prefix
      rest = rest.slice(colonIdx + 1)
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (const ch of ['/', '?', '#']) {
      const idx = rest.indexOf(ch)
      if (idx !== -1 && idx < end) end = idx
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  const qIdx = rest.indexOf('?')
  const hIdx = rest.indexOf('#')
  if (qIdx !== -1 && qIdx < pathEnd) pathEnd = qIdx
  if (hIdx !== -1 && hIdx < pathEnd) pathEnd = hIdx
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    const hIdx2 = rest.indexOf('#')
    if (hIdx2 === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, hIdx2)
      rest = rest.slice(hIdx2)
    }
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority string into userinfo, host and port. userinfo
 * and port are `null` when absent, and a string (possibly empty) when
 * present. host is always a string.
 */
export function splitAuthority(authority) {
  let rest = authority
  let userinfo = null
  const atIdx = rest.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = rest.slice(0, atIdx)
    rest = rest.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = rest.indexOf(':', searchFrom)
  let host, port
  if (colonIdx !== -1) {
    host = rest.slice(0, colonIdx)
    port = rest.slice(colonIdx + 1)
  } else {
    host = rest
    port = null
  }
  return { userinfo, host, port }
}

/**
 * Uppercases the hex digits of every `%XX` triplet in `s` and decodes
 * the ones that encode an unreserved character. Throws `UriError` when
 * a `%` is not followed by two hexadecimal digits.
 */
function normalizePercentEncoding(s) {
  let result = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      const h1 = s[i + 1]
      const h2 = s[i + 2]
      if (h1 === undefined || h2 === undefined || !HEX.test(h1) || !HEX.test(h2)) {
        throw new UriError('truncated')
      }
      const hex = (h1 + h2).toUpperCase()
      const ch = String.fromCharCode(parseInt(hex, 16))
      result += UNRESERVED.test(ch) ? ch : '%' + hex
      i += 2
    } else {
      result += s[i]
    }
  }
  return result
}

function normalizeComponent(value, name) {
  if (value === null) return null
  try {
    return normalizePercentEncoding(value)
  } catch {
    throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
}

/** Removes dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

function serialize({ scheme, authority, path, query, fragment }) {
  let s = ''
  if (scheme !== null) s += scheme + ':'
  if (authority !== null) s += '//' + authority
  s += path
  if (query !== null) s += '?' + query
  if (fragment !== null) s += '#' + fragment
  return s
}

/**
 * Normalizes a parsed reference and returns its string form. Applies,
 * in order: scheme lowercasing, percent-encoding normalization (path,
 * then userinfo, host, query and fragment, in that order, throwing on
 * the first truncated encoding), host lowercasing, default-port
 * removal, dot-segment removal, and the authority-implies-root-path
 * rule.
 */
export function normalize(components) {
  let { scheme, authority, path, query, fragment } = components
  if (scheme !== null) scheme = asciiLower(scheme)

  let userinfo = null
  let host = null
  let port = null
  if (authority !== null) {
    ;({ userinfo, host, port } = splitAuthority(authority))
  }

  path = normalizeComponent(path, 'path')
  userinfo = normalizeComponent(userinfo, 'userinfo')
  host = normalizeComponent(host, 'host')
  query = normalizeComponent(query, 'query')
  fragment = normalizeComponent(fragment, 'fragment')

  if (host !== null) host = asciiLower(host)

  if (port !== null) {
    const isDefault = scheme !== null && DEFAULT_PORTS[scheme] === port
    if (port === '' || isDefault) port = null
  }

  if (authority !== null) {
    let a = ''
    if (userinfo !== null) a += userinfo + '@'
    a += host
    if (port !== null) a += ':' + port
    authority = a
  }

  path = removeDotSegments(path)
  if (authority !== null && path === '') path = '/'

  return serialize({ scheme, authority, path, query, fragment })
}

/**
 * Merges a relative reference path onto a base path per RFC 3986
 * section 5.2.3.
 */
function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  const prefix = idx === -1 ? '' : base.path.slice(0, idx + 1)
  return prefix + refPath
}

/**
 * Resolves a parsed reference against a parsed base per RFC 3986
 * section 5.2.2, in its strict form. Returns an unnormalized component
 * set; pass it to `normalize` to get the final string.
 */
export function resolve(base, ref) {
  let target
  if (ref.scheme !== null) {
    target = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.authority !== null) {
    target = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
    }
  } else {
    const path = ref.path.startsWith('/') ? removeDotSegments(ref.path) : removeDotSegments(mergePaths(base, ref.path))
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path,
      query: ref.query,
    }
  }
  target.fragment = ref.fragment
  return target
}
"}

