 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/** Raised for any input that fails to parse; carries the message to report. */
export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(line, message) {
  throw new ParseError(line === null ? `error: ${message}` : `error: line ${line}: ${message}`)
}

/**
 * Parses the raw election text into `{ candidates, ballots }`, where
 * `candidates` is the declared list of names and `ballots` is a list of
 * `{ count, names }` entries. Throws `ParseError` on any invalid input.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 2) fail(lineNumber, 'expected candidates <name>...')
      const names = tokens.slice(1)
      for (const name of names) {
        if (!NAME_RE.test(name)) fail(lineNumber, `invalid candidate name ${name}`)
        if (candidateSet.has(name)) fail(lineNumber, `candidate ${name} is declared twice`)
        candidateSet.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) fail(lineNumber, 'candidates must be declared once, before any ballot')
      if (tokens.length < 3) fail(lineNumber, 'expected ballot <count> <candidate>...')
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) fail(lineNumber, 'count must be a positive integer')
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) fail(lineNumber, `unknown candidate ${name}`)
        if (seen.has(name)) fail(lineNumber, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(countToken), names })
    } else {
      fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail(null, 'no candidates')

  return { candidates, ballots }
}
"}

