{"file_path":"src/input.js","content":"/**
 * Splits raw stdin text into lines (dropping the empty tail a trailing
 * newline leaves) and then into the three documents separated by `%%%`
 * lines.
 *
 * @param {string} text
 * @returns {[string[], string[], string[]]}
 */
export function parseInput(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const parts = [[]]
  for (const line of rawLines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) throw new Error('expected three parts separated by %%%')
  return [parts[0], parts[1], parts[2]]
}
"}

