 * Recursive-descent parser for a formula body, built on the token stream
 * from lexer.js. Produces an AST of the node shapes documented below, or
 * throws ParseError when the token stream is not a formula the grammar
 * accepts.
 *
 * Precedence, loosest to tightest: comparisons, `+`/`-`, `*`/`/`, `^`, then
 * a leading unary `+`/`-`. Comparisons and the additive/multiplicative
 * levels are left-associative; `^` is right-associative and unary binds
 * tighter than it (so `-2^2` is `(-2)^2`).
 *
 * A range (`A1:B3`) parses as an atom anywhere an atom is accepted; whether
 * it is used directly as a function argument (and so expands to many
 * values) or elsewhere (and so is `#ERR!`) is a matter for evaluation, not
 * parsing.
 */

import { parseWordAddress } from './address.js'
import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (t.type !== type) throw new ParseError(`expected ${type}, got ${t.type}`)
    return t
  }
}

export function parseFormula(body) {
  let tokens
  try {
    tokens = tokenize(body)
  } catch (e) {
    if (e instanceof LexError) throw new ParseError(e.message)
    throw e
  }
  const ts = new TokenStream(tokens)
  const expr = parseComparison(ts)
  ts.expect('EOF')
  return expr
}

function parseComparison(ts) {
  let left = parseAdditive(ts)
  while (COMPARISON_OPS.has(ts.peek().type)) {
    const op = ts.next().type
    const right = parseAdditive(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  while (ts.peek().type === '+' || ts.peek().type === '-') {
    const op = ts.next().type
    const right = parseMultiplicative(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  while (ts.peek().type === '*' || ts.peek().type === '/') {
    const op = ts.next().type
    const right = parsePower(ts)
    left = { type: 'binop', op, left, right }
  }
  return left
}

function parsePower(ts) {
  const left = parseUnary(ts)
  if (ts.peek().type === '^') {
    ts.next()
    const right = parsePower(ts)
    return { type: 'binop', op: '^', left, right }
  }
  return left
}

function parseUnary(ts) {
  if (ts.peek().type === '-' || ts.peek().type === '+') {
    const op = ts.next().type
    const operand = parseUnary(ts)
    return { type: 'unary', op, operand }
  }
  return parseAtom(ts)
}

function parseAtom(ts) {
  const t = ts.peek()
  if (t.type === 'NUMBER') {
    ts.next()
    return { type: 'num', value: t.value }
  }
  if (t.type === '(') {
    ts.next()
    const expr = parseComparison(ts)
    ts.expect(')')
    return expr
  }
  if (t.type === 'WORD') {
    ts.next()
    const upper = t.value.toUpperCase()
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }
    if (ts.peek().type === '(') {
      return parseCall(ts, upper)
    }
    if (ts.peek().type === ':') {
      ts.next()
      const t2 = ts.expect('WORD')
      const from = parseWordAddress(t.value)
      const to = parseWordAddress(t2.value)
      return { type: 'range', from, to }
    }
    const addr = parseWordAddress(t.value)
    return { type: 'address', addr }
  }
  throw new ParseError(`unexpected token ${t.type}`)
}

function parseCall(ts, name) {
  ts.expect('(')
  const args = []
  if (ts.peek().type !== ')') {
    args.push(parseComparison(ts))
    while (ts.peek().type === ',') {
      ts.next()
      args.push(parseComparison(ts))
    }
  }
  ts.expect(')')
  return { type: 'call', name, args }
}

export function isKnownFunction(name) {
  return CALL_NAMES.has(name)
}
"}

