{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-xSFDmu/src/eval.js","content":"/**
 * Evaluates a parsed sheet: cell values (with cycle detection) and, for
 * `deps` mode, the addresses a formula's AST names directly.
 */

import { compareAddresses } from './address.js'
import { parseFormula, ParseError } from './parser.js'
import {
  num,
  bool,
  err,
  literalToValue,
  coerceNumber,
  compareValues,
  ERR_DIV0,
  ERR_REF,
  ERR_VALUE,
  ERR_CYCLE,
  ERR_NAME,
  ERR_GENERIC,
} from './values.js'

const KNOWN_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

/** Parses (and caches) the formula AST for a cell's content, if it is one. */
function getFormulaAst(cell) {
  if (cell.astComputed) return cell.ast
  cell.astComputed = true
  if (cell.content.startsWith('=')) {
    try {
      cell.ast = parseFormula(cell.content.slice(1))
    } catch (e) {
      if (e instanceof ParseError) {
        cell.ast = null
      } else {
        throw e
      }
    }
  } else {
    cell.ast = undefined // not a formula
  }
  return cell.ast
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells // Map<key, {content}>
    this.cache = new Map()
    this.visiting = new Set()
  }

  valueOf(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    const cell = this.cells.get(key)
    if (!cell) {
      const v = num(0)
      this.cache.set(key, v)
      return v
    }
    if (this.visiting.has(key)) {
      this.cache.set(key, ERR_CYCLE)
      return ERR_CYCLE
    }
    this.visiting.add(key)
    let v
    try {
      v = this.evalCell(cell)
    } finally {
      this.visiting.delete(key)
    }
    this.cache.set(key, v)
    return v
  }

  evalCell(cell) {
    if (!cell.content.startsWith('=')) return literalToValue(cell.content)
    const ast = getFormulaAst(cell)
    if (ast === null) return ERR_GENERIC
    return this.evalTopExpr(ast)
  }

  /** Evaluates an AST node in a normal (non-argument) expression position. */
  evalExpr(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'range':
        return ERR_GENERIC
      case 'address':
        return this.evalAddress(node)
      case 'unary':
        return this.evalUnary(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  /** The whole formula is just an expression (a range at the top level is misplaced). */
  evalTopExpr(node) {
    return this.evalExpr(node)
  }

  evalAddress(node) {
    if (!node.addr.valid) return ERR_REF
    return this.valueOf(node.addr.key)
  }

  evalUnary(node) {
    const v = this.evalExpr(node.operand)
    if (v.type === 'error') return v
    const c = coerceNumber(v)
    if (!c.ok) return ERR_VALUE
    const result = node.op === '-' ? -c.value : c.value
    return finiteOrDiv0(result)
  }

  evalBinop(node) {
    const left = this.evalExpr(node.left)
    const right = this.evalExpr(node.right)
    if (left.type === 'error') return left
    if (right.type === 'error') return right
    if (isComparisonOp(node.op)) {
      const cmp = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(cmp === 0)
        case '<>':
          return bool(cmp !== 0)
        case '<':
          return bool(cmp < 0)
        case '<=':
          return bool(cmp <= 0)
        case '>':
          return bool(cmp > 0)
        case '>=':
          return bool(cmp >= 0)
      }
    }
    const cl = coerceNumber(left)
    if (!cl.ok) return ERR_VALUE
    const cr = coerceNumber(right)
    if (!cr.ok) return ERR_VALUE
    let result
    switch (node.op) {
      case '+':
        result = cl.value + cr.value
        break
      case '-':
        result = cl.value - cr.value
        break
      case '*':
        result = cl.value * cr.value
        break
      case '/':
        result = cl.value / cr.value
        break
      case '^':
        result = Math.pow(cl.value, cr.value)
        break
      default:
        throw new Error(`unknown operator ${node.op}`)
    }
    return finiteOrDiv0(result)
  }

  /** Expands a range (as a direct function argument) into its cell values. */
  expandRangeValues(node) {
    if (!node.from.valid || !node.to.valid) return [ERR_REF]
    const c1 = node.from.col
    const c2 = node.to.col
    const r1 = node.from.row
    const r2 = node.to.row
    const colLo = Math.min(c1, c2)
    const colHi = Math.max(c1, c2)
    const rowLo = Math.min(r1, r2)
    const rowHi = Math.max(r1, r2)
    const values = []
    for (let col = colLo; col <= colHi; col++) {
      for (let row = rowLo; row <= rowHi; row++) {
        values.push(this.valueOf(colRowKey(col, row)))
      }
    }
    return values
  }

  /** Evaluates a call argument that must yield exactly one value. */
  evalArgSingle(node) {
    if (node.type === 'range') {
      const values = this.expandRangeValues(node)
      const firstErr = values.find((v) => v.type === 'error')
      if (firstErr) return firstErr
      if (values.length !== 1) return ERR_VALUE
      return values[0]
    }
    return this.evalExpr(node)
  }

  /** Flattens a list of argument AST nodes into a value list, ranges expanded. */
  flattenArgs(args) {
    const values = []
    for (const node of args) {
      if (node.type === 'range') {
        values.push(...this.expandRangeValues(node))
      } else {
        values.push(this.evalExpr(node))
      }
    }
    return values
  }

  evalCall(node) {
    const name = node.name
    if (!KNOWN_FUNCTIONS.has(name)) return ERR_NAME
    if (name === 'IF') return this.evalIf(node)
    if (name === 'ABS') return this.evalAbs(node)
    // SUM, MIN, MAX, COUNT, AVG
    if (node.args.length < 1) return ERR_GENERIC
    const values = this.flattenArgs(node.args)
    const firstErr = values.find((v) => v.type === 'error')
    if (firstErr) return firstErr
    if (name === 'COUNT') {
      const count = values.filter((v) => v.type === 'number').length
      return num(count)
    }
    const nums = []
    for (const v of values) {
      const c = coerceNumber(v)
      if (!c.ok) return ERR_VALUE
      nums.push(c.value)
    }
    switch (name) {
      case 'SUM':
        return finiteOrDiv0(nums.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finiteOrDiv0(Math.min(...nums))
      case 'MAX':
        return finiteOrDiv0(Math.max(...nums))
      case 'AVG':
        return finiteOrDiv0(nums.reduce((a, b) => a + b, 0) / nums.length)
      default:
        throw new Error(`unhandled function ${name}`)
    }
  }

  evalAbs(node) {
    if (node.args.length !== 1) return ERR_GENERIC
    const v = this.evalArgSingle(node.args[0])
    if (v.type === 'error') return v
    const c = coerceNumber(v)
    if (!c.ok) return ERR_VALUE
    return finiteOrDiv0(Math.abs(c.value))
  }

  evalIf(node) {
    if (node.args.length !== 3) return ERR_GENERIC
    const condVal = this.evalArgSingle(node.args[0])
    if (condVal.type === 'error') return condVal
    let condBool
    if (condVal.type === 'bool') condBool = condVal.value
    else if (condVal.type === 'number') condBool = condVal.value !== 0
    else return ERR_VALUE
    const branch = condBool ? node.args[1] : node.args[2]
    return this.evalArgSingle(branch)
  }
}

function isComparisonOp(op) {
  return op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>='
}

function finiteOrDiv0(n) {
  return Number.isFinite(n) ? num(n) : ERR_DIV0
}

function colRowKey(col, row) {
  return `${colToLetters(col)}${row}`
}

function colToLetters(col) {
  let letters = ''
  let c = col
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters
}

/** Collects the addresses (ranges expanded) a formula names directly. */
export function collectDeps(cell) {
  const ast = getFormulaAst(cell)
  if (!ast) return []
  const found = new Map() // key -> {col,row}
  walk(ast)
  const list = [...found.values()]
  list.sort(compareAddresses)
  return list.map((a) => `${a.letters}${a.row}`)

  function addAddr(addr) {
    if (addr && addr.valid) found.set(addr.key, addr)
  }

  function walk(node) {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'address':
        addAddr(node.addr)
        return
      case 'range': {
        if (!node.from.valid || !node.to.valid) return
        const colLo = Math.min(node.from.col, node.to.col)
        const colHi = Math.max(node.from.col, node.to.col)
        const rowLo = Math.min(node.from.row, node.to.row)
        const rowHi = Math.max(node.from.row, node.to.row)
        for (let col = colLo; col <= colHi; col++) {
          for (let row = rowLo; row <= rowHi; row++) {
            found.set(`${colToLetters(col)}${row}`, { letters: colToLetters(col), row, col })
          }
        }
        return
      }
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const a of node.args) walk(a)
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }
}

export { getFormulaAst }
"}

