/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, collectDeps } from './eval.js'
import { formatValue } from './values.js'

function readStdin() {
  const chunks = []
  const fs = require_fs()
  const fd = 0
  const buf = Buffer.alloc(65536)
  let n
  while ((n = fs.readSync(fd, buf, 0, buf.length)) > 0) {
    chunks.push(Buffer.from(buf.subarray(0, n)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // Isolated helper so the only synchronous stdin reading path is here.
  // eslint-disable-next-line global-require
  return globalThis.__fs ?? (globalThis.__fs = requireFsModule())
}

function requireFsModule() {
  // Dynamic import isn't synchronous; use the builtin require via module.
  // Node's ESM has no top-level require, so build one.
  // eslint-disable-next-line no-undef
  return createRequire()
}

function createRequire() {
  const { createRequire: cr } = /* eslint-disable-next-line */ nodeModule()
  return cr(import.meta.url)('node:fs')
}

function nodeModule() {
  // Lazily resolved to avoid a top-level require in an ESM file.
  return globalThis.__module ?? (globalThis.__module = importModuleSync())
}

function importModuleSync() {
  // 'module' is available as a Node built-in accessible via process.binding-free API.
  // We use the documented way: import 'node:module' synchronously isn't possible in ESM,
  // so fall back to process.mainModule-free createRequire imported at top instead.
  throw new Error('unreachable')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(e.message + '\n')
      process.exit(2)
    }
    throw e
  }

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet.cells)
    for (const key of sheet.order) {
      const value = evaluator.valueOf(key)
      lines.push(`${key}=${formatValue(value)}`)
    }
  } else {
    for (const key of sheet.order) {
      const cell = sheet.cells.get(key)
      const deps = collectDeps(cell)
      lines.push(deps.length ? `${key}: ${deps.join(' ')}` : `${key}:`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
